 OR (p_outcome='sent' AND (p_result_hash IS NULL OR octet_length(p_result_hash)<>32 OR p_error_code IS NOT NULL))
 OR (p_outcome IN ('retry','dead') AND (p_result_hash IS NOT NULL OR p_error_code IS NULL OR p_error_code !~ '^[A-Z][A-Z0-9_]{0,63}$'))
