 fingerprint:=sha256(convert_to(jsonb_build_array(p_outcome,encode(p_result_hash,'hex'),p_error_code,p_retry_seconds)::text,'UTF8'));
 SELECT * INTO item FROM photo.billing_outbox WHERE id=p_message FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'BILLING_OUTBOX_NOT_FOUND';END IF;
 IF item.worker_id IS DISTINCT FROM p_worker OR item.processing_token IS DISTINCT FROM p_fence
